-- Lee 2026-11-04 "건물 사진을 왜 안 넣어?": 근무지 건물 사진을 images에. 사진은 ops-insert-job(storage_path)으로 먼저 올림. 입구 ingest_job job_id+update_fields.
select public.ingest_job($ingest${"title": "New Team Robotics Vietnam tuyển 02 trợ lý nhân sự (tiếng Trung) – 18 triệu/tháng", "company": "NEW TEAM ROBOTICS VIETNAM", "category": "van_phong", "occupation_code": "4406", "occupation_evidence": "Tuyển dụng, sàng lọc CV, sắp xếp phỏng vấn.", "salary": "18.000.000đ/tháng", "salary_min": 18000000, "salary_period": "month", "location": "Nhà xưởng NX 2-2, lô đất CN1-2 và CN1-3, KCN Yên Phong (khu mở rộng), xã Yên Trung, Bắc Ninh", "employer_phone": "0787486194", "contact_zalo": "0787486194", "age_max": 30, "num_hires": 2, "description": "[source:facebook] CƠ HỘI VIỆC LÀM HẤP DẪN TẠI BẮC NINH\nNEW TEAM ROBOTICS VIETNAM TUYỂN DỤNG\nTHU NHẬP 18 TRIỆU/THÁNG – CÓ THỂ TĂNG THÊM 10% THEO CHÍNH SÁCH CÔNG TY!\nVị trí: TRỢ LÝ NHÂN SỰ – 02 NGƯỜI\nYêu cầu:\n• Không quá 30 tuổi.\n• Có kinh nghiệm làm nhân sự, nắm vững quy trình cơ bản.\n• Giao tiếp tiếng Trung lưu loát.\n• Thành thạo Word, Excel, PowerPoint.\n• Cẩn thận, trách nhiệm, chủ động trong công việc.\nCông việc:\n• Tuyển dụng, sàng lọc CV, sắp xếp phỏng vấn.\n• Làm thủ tục nhận việc, nghỉ việc.\n• Quản lý chấm công, hồ sơ và dữ liệu nhân sự.\n• Hỗ trợ các công việc hành chính nhân sự khác.\nQuyền lợi:\n• Thu nhập hấp dẫn, có cơ hội tăng lương.\n• Môi trường làm việc chuyên nghiệp, đội ngũ trẻ.\n• Cơ hội phát triển và thăng tiến lâu dài.\nĐịa điểm: Nhà xưởng NX 2-2 (thuộc nhà xưởng số 2), lô đất CN1-2 và CN1-3, KCN Yên Phong (khu mở rộng), xã Yên Trung, TP. Bắc Ninh.\nLiên hệ/Zalo: 0787 486 194\nỨng viên vui lòng gửi CV để được trao đổi chi tiết!", "source_text": "CƠ HỘI VIỆC LÀM HẤP DẪN TẠI BẮC NINH\nNEW TEAM ROBOTICS VIETNAM TUYỂN DỤNG\nTHU NHẬP 18 TRIỆU/THÁNG – CÓ THỂ TĂNG THÊM 10% THEO CHÍNH SÁCH CÔNG TY!\nVị trí: TRỢ LÝ NHÂN SỰ – 02 NGƯỜI\nYêu cầu:\n• Không quá 30 tuổi.\n• Có kinh nghiệm làm nhân sự, nắm vững quy trình cơ bản.\n• Giao tiếp tiếng Trung lưu loát.\n• Thành thạo Word, Excel, PowerPoint.\n• Cẩn thận, trách nhiệm, chủ động trong công việc.\nCông việc:\n• Tuyển dụng, sàng lọc CV, sắp xếp phỏng vấn.\n• Làm thủ tục nhận việc, nghỉ việc.\n• Quản lý chấm công, hồ sơ và dữ liệu nhân sự.\n• Hỗ trợ các công việc hành chính nhân sự khác.\nQuyền lợi:\n• Thu nhập hấp dẫn, có cơ hội tăng lương.\n• Môi trường làm việc chuyên nghiệp, đội ngũ trẻ.\n• Cơ hội phát triển và thăng tiến lâu dài.\nĐịa điểm: Nhà xưởng NX 2-2 (thuộc nhà xưởng số 2), lô đất CN1-2 và CN1-3, KCN Yên Phong (khu mở rộng), xã Yên Trung, TP. Bắc Ninh.\nLiên hệ/Zalo: 0787 486 194\nỨng viên vui lòng gửi CV để được trao đổi chi tiết!", "source_url": "https://www.facebook.com/groups/302285210225581/posts/2658702567917155/", "images": ["fb/new-teamrobotics-20261104.png"], "job_id": 5438, "update_fields": ["images"], "channel": "sql_file"}$ingest$::jsonb) as job_id \gset
select step, outcome from public.job_ingest_log where raw_id = (select max(id) from public.job_ingest_raw where job_id = :job_id) order by array_position(array['preserve','dedup','occupation','location','publication'], step);
select id, images, active, admin_hidden from public.local_jobs where id = :job_id;
